effect.shader:
const int TAPS = 8;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  vec4 blur = vec4(0.0);
  for (int i = 0; i < TAPS; i++){
    float ang = float(i) * 6.2831853 / float(TAPS);
    blur += texture2DCv(inputImg.texture, uv + vec2(cos(ang), sin(ang)) * radius);
  }
  blur /= float(TAPS);
  float ba = max(blur.a, 1e-4);
  vec3 bc = mix(blur.rgb / ba, vec3(gmLum(blur.rgb / ba)), desat);
  float sa = max(src.a, 1e-4);
  vec3 sc = src.rgb / sa;
  vec3 glow = vec3(1.0) - (vec3(1.0) - sc) * (vec3(1.0) - bc * screenAmt * mixAmt);
  float a = src.a;
  gl_FragColor = vec4(clamp(glow, 0.0, 1.0) * a, a);
}
